const oncallOpenSourceAlerts = `-- name: OncallOpenSourceAlerts :exec
INSERT INTO oncall_alerts(organization_id,policy_id,incident_id,conversation_id)
SELECT p.organization_id,p.id,i.id,c.id FROM escalation_policies p
LEFT JOIN status_incidents i ON i.organization_id=p.organization_id AND i.id=$1::bigint AND i.status<>'resolved'
LEFT JOIN conversations c ON c.organization_id=p.organization_id AND c.id=$2::bigint AND c.priority='urgent' AND c.status NOT IN ('resolved','closed') AND c.deleted_at IS NULL
WHERE p.organization_id=$3 AND p.enabled AND ((p.incidents AND i.id IS NOT NULL) OR (p.urgent_conversations AND c.id IS NOT NULL))
ON CONFLICT DO NOTHING
`

type OncallOpenSourceAlertsParams struct {
	IncidentID     pgtype.Int8 `json:"incident_id"`
	ConversationID pgtype.Int8 `json:"conversation_id"`
	OrganizationID int64       `json:"organization_id"`
}

func (q *Queries) OncallOpenSourceAlerts(ctx context.Context, arg OncallOpenSourceAlertsParams) error {
	_, err := q.db.Exec(ctx, oncallOpenSourceAlerts, arg.IncidentID, arg.ConversationID, arg.OrganizationID)
	return err
}

